def link(u,t):return f'<a href="{u}" target="_blank" rel="noopener noreferrer">{t} ↗<span class="sr-only"> (opens in a new tab)</span></a>'
def p(t):return '<p>'+t+'</p>'
def table(h,rows):return '<div class="table-wrap" tabindex="0" role="region" aria-label="Comparison table, scroll horizontally"><table><thead><tr>'+''.join('<th>'+x+'</th>'for x in h)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>'for x in r)+'</tr>'for r in rows)+'</tbody></table></div>'
PAGES=[
('platforms','Brotato Platforms and Prices — PC, Console and Mobile','Where to buy base Brotato: Steam, Xbox, Switch, PlayStation and iOS/Android, with price notes and the Primal Dread platform status. Prices checked 26 November 2026.','Base Brotato is listed on Steam for Windows, Mac and Linux, on Xbox, on Nintendo Switch and Switch 2, on PlayStation 4 and 5, and as a mobile port on iOS and Android. Primal Dread is PC-only at the time of checking; the publisher announced console and mobile versions for early 2027.','base',[
('table','Where to buy the base game',table(['Platform','Status we checked','Price note'],[['Steam (Windows, Mac, Linux)','Listed; Steam Deck verified','Base price $4.99. 2026 sales seen as low as $2.99 in price-history trackers.'],['Xbox One and Xbox Series','Listed; Xbox Cloud Gaming supported; included with PC Game Pass','Store price around $4.99 on resale-key trackers; check the Xbox store.'],['Nintendo Switch and Switch 2','Listed','No current eShop price confirmed; check the eShop for your region.'],['PlayStation 4 and PlayStation 5','Listed as digital','PS5 price not confirmed in our sources.'],['iOS and Android','Mobile port by Erabit Studios, launched 28 March 2023','Price model conflicts: launched as premium, later listed as free-to-play with premium options. Check the store listing.']])+p('Price and listing checks rely on Steam price-history trackers, the Main Gamers platform listing, gg.deals and the Wikipedia and launch-news reports. Prices vary by region and date.')),
('primal','Primal Dread platform status',p('Primal Dread is expansion content. At the checked date it is available on PC through Steam. The publisher briefing announced console and mobile versions for early 2027, without an exact day. A PC DLC purchase does not give mobile ownership, so check each store before buying.')),
('check','Before you buy',p('Check your region, the platform price, and whether the copy is the base game or the Primal Dread expansion. For mobile, read the current store listing, because the free and premium model conflicts across sources. Storefront prices move often.')),
]),
('unlocks','Brotato Unlocks — Baby, Beast Master, Fisherman and More','Source-checked unlock conditions for Brotato characters and Celery Tea, where three or more independent sites agree. Pet and conflicting entries are listed separately.','Baby, Beast Master, Fisherman, Farmer, Generalist and Gangster have unlock conditions that the checked sites agree on, and Celery Tea unlocks by winning a run with Baby. Pet unlock conditions and a few item entries conflict between sources, so they are not listed here.','unlock-characters',[
('characters','Character unlock conditions',table(['Character','Unlock condition','Sources that agree'],[['Baby','Reach level 10 before wave 6 (Fast Learner)','brotatodb, Brotator, brotato.app'],['Beast Master','Unlock the Catling Gun, Bonk Dog, Bot-O-Mine, Blazemander and Lootworm items','Brotator, brotato.app'],['Fisherman','Get 2 Bait during a run (Baited)','brotatodb, Brotator, brotato.app'],['Farmer','Reach +200 Harvesting','brotatodb, Brotator, brotato.app'],['Generalist','Collect 2000 materials','brotatodb, Brotator, brotato.app'],['Gangster','Reroll 10 times in a single shop','Brotator, brotato.app']])+p('Two or three independent sites give each row above. The sites are community databases and the Brotato Wiki; check the in-game unlock screen if a condition does not match.')),
('items','Item unlock',table(['Item','Unlock condition','Sources that agree'],[['Celery Tea','Win a run with Baby','brotatodb, brotato.app']])+p('Celery Tea is the reward for winning a run with Baby. Win the run with Baby itself, not any character.')),
('notes','Not listed here',p('Pet unlock conditions differ across sources, so this page omits them. Scapegoat also has conflicting entries: one database ties it to a Beast Master win, while another lists it as a base-pool item with no unlock challenge. Check the in-game Codex for those entries before planning a run around them.')),
]),
('bosses','Brotato Abyss Bosses — Dead Whale and Eel Stats','Dead Whale and Eel HP, speed, damage and phase triggers from two independent data sites. Abyssal Terrors DLC bosses, source-checked.','Dead Whale and Eel both reach 31,625 HP at wave 20 and gain 875 HP per wave from 15,000 at wave 1. Dead Whale moves at speed 200 and Eel at speed 150. Both are Abyssal Terrors bosses, so check your Item Sets before planning a run around them.','abyss-bosses',[
('stats','Read the boss stats',table(['Boss','Wave 1 HP','HP per wave','Wave 20 HP','Speed','Damage (contact / projectile)','Materials'],[['Dead Whale','15,000','+875','31,625 (Danger 5: 33,206)','200','30 / 23 (Danger 5: 41 / 32)','10'],['Eel','15,000','+875','31,625 (Danger 5: 33,206)','150','30 / 23 (Danger 5: 41 / 32)','10']])+p('Two data sites report the same values: the Brotato Wiki Enemies page and brotatodb. The Danger 5 numbers come from the wiki table. Stats can change with a balance patch.')),
('phases','Phase triggers',table(['Boss','Phase','Trigger','Behaviour'],[['Dead Whale','Phase 0','Start','Moves randomly and fires 3 waves of 6 projectiles at regular intervals.'],['Dead Whale','Phase 1','70% HP, every 20 seconds','Chases the player, charging while firing projectiles in all directions.'],['Dead Whale','Phase 2','40% HP, every 45 seconds','Chases more often and spawns a large circle of projectiles around itself.'],['Eel','Phase 0','Start','Chases the player and fires a stream of projectiles.'],['Eel','Phase 1','70% HP, every 25 seconds','Moves randomly and spawns a spiral of projectiles centred on the player.'],['Eel','Phase 2','40% HP, every 55 seconds','Keeps chasing while spawning spirals and four lines of projectiles that orbit it.']])+p('The wiki labels these as Mutation 0, 1 and 2. They are boss phases, not the Mutation path in the Evolution system. Behaviour descriptions come from the Brotato Wiki Enemies page only.')),
('plan','Plan around speed and phases',p('Dead Whale is faster than Eel on the source tables (200 against 150), so keep a movement lane open when it charges. Below 40% HP, Eel’s phase repeats every 55 seconds on the wiki timing, so plan burst damage around that interval rather than a fixed kill window.')+p('Use the <a href="/brotato/evolution/">Evolution guide</a> to decide whether your build supports the damage needed for these HP values.')),
('scope','What this page does not cover',p('We have not confirmed the exact wave at which bosses appear in every run, the drop rules beyond the Materials value, or any version after the checked date. Check the in-game Codex when a stat differs from this table.')),
]),
('shop','Brotato Shop Guide — Recycling, Locks and Reroll Costs','Read the Brotato shop layout, recycle items for materials, and plan around locks and rerolls. Source-based rules with conflicts marked.','Use Lock to keep an offer for the next visit, Reroll to refresh the offers for a material cost, and Recycle to convert an owned item or weapon back into materials. Recycle values depend on the current price and on modifiers such as the Recycling Machine.','shop',[
('layout','Read the shop layout',table(['Area','What it shows','What to check'],[['Offers (four cards)','Name, type, stats and price in materials','Compare price against the stat gain before buying.'],['Lock button under each offer','Locked offers keep their current price and stay in the shop while locked.','Lock the offer you plan to buy before rerolling.'],['Reroll button, top right','Refreshes the offers for a material fee','The fee rises with each reroll in the same shop. Set the budget first.'],['Items and Weapons panels','Your current inventory and weapon slots','Recycle here to free slots or raise materials.']])+p('The layout above matches a wave 2 capture. Item prices rise with each wave. The Brotato Wiki Shop page describes the lock and reroll rules.')),
('recycle','Recycle for materials',p('Recycling returns a share of an item’s value and removes the item or weapon. Sources we checked agree on the base return of 25%. A Recycling Machine raises the return to 60%, and the Entrepreneur bonus adds 25% on top, for 85% in total. The payout follows the current price, so coupons and inflation can change it.')+p('Equipped weapons can be recycled according to a shop guide. Sources conflict on whether items bought from the shop can be sold freely, so check the in-game tooltip before planning a sale. Confirm the percentages on your own copy, since balance patches can change them.')),
('achievement','Recycling achievement',p('The Recycling achievement requires recycling 12 weapons from inventory during a single run. Sources report that it triggers when the 12th weapon is recycled. Plan the count across the run, not only at the end.')),
('next','Plan the next visit',p('If you cannot afford the offer you need, lock it, reroll only when the budget allows, and recycle surplus weapons to fund the plan. Use the <a href="/brotato/evolution/">Evolution guide</a> to decide whether the weapon you are buying belongs to a Mecha or Mutation route.')),
]),
('evolution','Brotato Evolution Guide — Choose Mecha or Mutation', 'Choose a Brotato Evolution path by build, enemy hazards and branch. Separate launch mechanics from November beta balance changes.', 'Choose Mecha to direct upgrades into weapons. Consider Mutation when item effects carry your run. Both directions also change enemies and their hazards.', 'mecha',[
('choose','Choose by what carries your run',table(['Your run','Consider','Reason'],[['Strong weapon core','Mecha','Choose reinforcement stats for the weapon plan.'],['Strong passive item package','Mutation','Random copied effects can develop that package.'],['Dying before scaling','Immediate survival','An unfinished scaling plan cannot rescue a dead run.']])+p('This is our editorial framework based on the '+link(NEWS,'developer’s Evolution explanation')+'. It is not a measured ranking.')),
('stat','What the Evolution stat does',p('Evolution is a Primal Dread stat. You push it toward Mecha or Mutation by picking up matching drops on the Jungle map. Mecha reinforces weapons and adds stats. Mutation copies item effects at random to multiply their value. Guides present the two paths as a choice, and this page does not claim that one run can complete both. Mecha parts can also come from dismantling mecha weapons in the shop, as the launch post describes. Guides give different threshold numbers, so read the in-game Evolution readout before planning around a specific value.')),
('drops','Follow the drops and watch the hazards',p('Mecha parts feed weapon reinforcement. The launch post also describes dismantling mecha weapons for additional parts. Mutation copies item effects randomly. Inspect the actual result before building your next shop decision around it.')+p('Mecha enemies introduce lasers and slowing oil. Mutant enemies spread acid. Leave an exit lane instead of crossing a puddle to collect every drop. Directed upgrades can be easier to plan around, while random copies require checking what the run actually gained.')),
('branch','Read the branch before copying a build',p('The 12 November Balancing Patch brings the tested Evolution changes to the Steam default branch. Mechanization grants +3% weapon damage per mecha power point, previously +5%. At eight mechanizations a weapon deals 208% of its base damage, previously 280%. Extra piercing and bounces are removed. Stat bonuses stop growing after rank eight, and Mecha Parts drop chance falls from 2% to 1.5%. Budget crowd coverage separately. Older launch builds and the 6 and 10 November beta notes describe earlier stages of these changes. '+link(BALANCE,'12 November balance notes'))),
('mutation-beta','Inspect Mutation results after the balance patch',p('Each mutation now puts its -1 Evolution on the Tumor. An item becomes mutant when it loses a negative modifier, and duplicate Tumor effects merge into one line. Mutation Fruit base drop chance rises from 3% to 4%, then falls by one percentage point every ten waves from wave 30, to a minimum of 1%. Inspect the Tumor when checking what a mutation changed. '+link(BALANCE,'12 November balance notes'))),
('snowball','Snowball after hotfix 1.2.0.3',p('Snowball now grants Elemental Damage only for items bought in the shop or found in crates. Tumor mutations no longer grant extra Elemental Damage on every mutation. Keep that distinction in mind when valuing another mutation for an elemental build. '+link(HOTFIX,'1.2.0.3 hotfix notes'))),
('beta4','Optional 1.2.0.4 beta: compare drops and item limits',p('The 17 November open beta raises Mecha Parts drops from 1.5% to 2.5% per mecha enemy killed. Chimera Cells changes from 10% mutation chance per copy with a five-copy limit to 15% with a four-copy limit. Treat these as beta rules when planning collections and purchases; the 12 November default-branch values above remain the reference for 1.2.0.3.')+p('This beta also keeps the Evolution damage bonus through in-run stat recalculations and fixes evolved enemy projectiles dealing only 1 damage. Leave room to dodge their normal damage rather than planning around that bug. '+link(BETA4,'Official 1.2.0.4 beta notes'))),
('shop','Make the next shop decision',p('If you lack damage, compare an immediate weapon upgrade with reinforcement. If collection is killing you, buy enough movement or defense to reach the next wave. With Mutation, inspect copied effects rather than assuming the best passive was selected. Reassess when the actual build changes.'))]),
('caveman','Brotato Caveman Build — Plan the Primitive Weapon Slot','Use a reported Caveman spear route and keep room for the Primitive-weapon shop cycle. Account for permanent fog and source limitations.', 'Plan the shop cycle before filling every slot. Two community reports describe five working weapons and a sixth slot for buying and burning a Primitive weapon. Spears are one reported route.', 'steam-3',[
('loop','Keep the purchase slot usable',p('The '+link(TIPS,'jldark89 report')+' uses five Spears as the working core and a temporary sixth weapon for the cycle. The '+link(CAVE,'earlier Caveman discussion')+' describes a similar slot plan with axes. Both are launch-week player reports. Confirm the current trait and qualifying weapon class on your character sheet.')+'<ol><li>Read which weapons qualify as Primitive.</li><li>Build a core that can clear the next wave without its temporary purchase.</li><li>Lock a suitable future purchase when available.</li><li>Complete the burn action in the shop and inspect the effect before leaving.</li></ol>'),
('core','Spend on weapons you will keep',p('Spears are the starting hypothesis from the newer report. Axes are an alternative in the earlier thread. Invest upgrades in the working core and preserve enough materials for the cycle. These reports establish a practical slot-management approach, not a universal best weapon or a guaranteed Nightmare clear.')),
('fog','Account for permanent fog',p('The 1.2.0.3 hotfix removes Boomerang from Caveman’s starting weapons, reversing the 12 November addition. The visibility tooltip for his permanent fog remains part of the 12 November changes. The reported Spear route remains a launch-week strategy. Reduced visibility makes chasing drops riskier. Judge an exit before committing to a path. '+link(NEWS,'Developer notes'))),
('beta','Mutation after the balance patch',p('The 12 November default-branch patch excludes Mutation copies of Caveman’s weapon-burning effect. Keep the shop cycle grounded in the character’s own ability. '+link(BALANCE,'12 November balance notes'))),
('beta4','Optional beta: burn before the next fog increase',p('In the 1.2.0.4 open beta announced on 17 November, burning at least one weapon stops fog from thickening on the next wave. Complete the burn in the shop before leaving when you want that next-wave benefit. The note does not say that burning removes existing fog, and this change is not established for the 1.2.0.3 default branch. '+link(BETA4,'Official beta fog change'))),
('failure','If the cycle keeps failing',p('Check weapon class, spare slot and purchase budget. If the cycle works but the next wave still kills you, improve the working core or learn the fog on a lower difficulty. A successful shop interaction alone does not show that the loadout can survive.'))]),
('veteran','Brotato Veteran Build — Ranged Route and Healing Checks','Plan a source-based Veteran ranged route for Primal Dread. Check healing restrictions, crowd coverage and launch-week weapon recommendations.', 'Start with a coherent ranged plan and read healing restrictions before buying sustain. A launch-week player recommends Machine Gun with flat Ranged Damage, Range and piercing. Treat it as a reported route.', 'veteran',[
('route','Support the gun you can use',p('The '+link(TIPS,'jldark89 report')+' recommends Machine Gun with ranged scaling and piercing for crowds. Its author plays Nightmare with wave retries enabled. That context matters when judging how forgiving the route is.')+p('Buy for the next problem. Groups reaching you call for crowd coverage and attack uptime. An elite living too long calls for inspecting weapon scaling and time spent firing. The advice here is editorial interpretation of that reported route.')),
('healing','Check restrictions before buying recovery',p('The '+link(NEWS,'official launch post')+' presents Veteran as a swarm-fighting character without time to heal. Read the exact current character sheet before buying HP regeneration, Life Steal or between-wave recovery. A bonus to a blocked recovery method may offer little value.')+p('Check any missing-health bonus on your installed version before intentionally fighting hurt. Leave enough health to survive an unexpected hit. We do not reproduce unverified numerical traits from launch-week summary sites.')),
('shop','A Veteran shop checklist','<ol><li>Concentrate weapons around the damage stat you are buying.</li><li>Check whether crowds die before reaching you.</li><li>Preserve a retreat lane with movement and defense.</li><li>Read restrictions before buying recovery.</li><li>Record map, difficulty, branch and active Item Sets when comparing builds.</li></ol>'),
('evolution','Choose Evolution after the core works',p('A weapon-focused route gives a reason to inspect Mecha reinforcement, while Mutation develops passives. After the 12 November Steam balance patch, mechanization grants +3% weapon damage per mecha power point and supplies no extra piercing or bounces. Check crowd coverage before investing in reinforcement. Use the <a href="/brotato/evolution/">Evolution guide</a> against your current tooltips.'))]),
('co-op','Brotato Co-op — Local Play, Remote Play and Mods','Choose Brotato local co-op or Steam Remote Play Together. Check the host, devices and current version before using old multiplayer mod instructions.', 'Steam lists shared-screen co-op and Remote Play Together. For friends elsewhere, Remote Play Together streams a host’s local session. Start with the supported route before seeking a multiplayer mod.', 'base',[
('choose','Choose for your devices',table(['Situation','Route','Check first'],[['One screen','Local co-op','Connect and join with the intended input devices.'],['Friends elsewhere on Steam','Remote Play Together','One host runs the game and invites guests.'],['Independent console copies','Platform-specific features','Steam streaming support does not establish cross-console matchmaking.'],['Old mod tutorial','Check date and game version','The instructions may predate supported local co-op.']])+p(link(BASE,'Brotato Steam features')+' and '+link('https://store.steampowered.com/remoteplay','Valve’s Remote Play guide')+' establish the Steam routes.')),
('crossplay','Cross-platform and online questions',p('Brotato has no built-in online matchmaking in the sources we checked, so cross-platform online play with strangers or across PC and console is not a supported route. On PC, Steam Remote Play Together is the way to play with friends elsewhere: one host runs the game and guests join through the Steam invite. Console copies stay on local co-op unless a platform announces a feature. Remote play quality depends on the host connection, so test a short session first. Community reports also describe lag and input problems, so treat them as a reason to check your setup rather than a guaranteed result. '+link(BASE,'Brotato Steam features')+' and '+link('https://store.steampowered.com/remoteplay','Valve’s Remote Play guide')+' are the sources for the Steam routes.')),
('remote','Set up Remote Play Together','<ol><li>The host launches the installed Steam game.</li><li>Invite the guest using Remote Play Together in the Steam friends list or overlay.</li><li>The guest accepts. Check allowed controller and keyboard inputs.</li><li>Join the local session and confirm each player controls a different character before starting.</li></ol>'+p('Valve documents one owner running the game while guests receive video and return inputs. The host computer and connection remain involved.')),
('trouble','If inputs or crates fail',p('When two people control one character, check Remote Play input permissions and local device assignment separately. Establish that controllers work locally before blaming the connection.')+p('After an update, reproduce crashes without mods. The November 3 patch includes a Survivor co-op crate fix. The 12 November default-branch patch fixes the Mecha Parts counter blocking co-op shop and inventory navigation. Match the symptom and branch before assuming a particular issue is fixed. '+link(NEWS,'Official patch notes'))),
('beta','Check weapon-popup navigation after updating',p('The 12 November default-branch patch fixes controller navigation getting stuck in a weapon popup when buttons are hidden. Hotfix 1.2.0.3 also fixes the missing gamepad selection after buying an item while the mouse cursor rests on another shop item. Check the installed branch when matching this symptom to a patch note. '+link(BALANCE,'12 November balance notes'))),
('next','Check the session before a long run',p('Agree on host, inputs and enabled content. Start a short unmodded session to verify controls. We have not tested remote parties, console pairings or shared progression. For mod conflicts, use the <a href="/brotato/mods/">compatibility checklist</a>.'))]),
('updates','Brotato Updates — New Dawn, 1.2 and the Beta Branch','Identify the update a Brotato guide describes. Separate New Dawn, free Item Sets, Primal Dread and November beta balance notes.', 'New Dawn, update 1.2 and Primal Dread are different content labels. The 12 November Steam Balancing Patch brings the tested Evolution changes to the default branch. The optional 1.2.0.4 beta adds another set of weapon, fog and Evolution changes. Check branch and Item Sets before copying a build.', 'item-set',[
('labels','Match the label to the task',table(['Label','Practical meaning'],[['New Dawn','A separately listed update in Item Sets. Match its toggle when reproducing older content.'],['Update 1.2','Free Item Set menu, older-character and Nightmare adjustments.'],['Primal Dread','Paid expansion with Jungle and Evolution.'],['1.2.0.1','November 3 post-launch patch.'],['1.2.0.2.beta-0','November 6 optional balance beta.'],['1.2.0.2.beta-1','November 10 optional beta, with further Evolution, shop and Jungle changes.'],['12 November Balancing Patch','Tested Evolution changes released on the Steam default branch.'],['1.2.0.3','13 November default-branch hotfix: Caveman starting weapon reversal, Snowball mutation fix and gamepad/foot fixes.'],['1.2.0.4 open beta','17 November optional test: weapon rebalancing, Caveman fog and Evolution drop changes.']])+p(link(NEWS,'Developer update history')+' documents the November changes.')),
('sets','Reproduce a guide with Item Sets',p('The 1.2 announcement introduces switches for expansions and free updates. It gives disabling Paws & Claws while leaving other content active as an example. Open Item Sets from Character Selection and compare the setup with the guide.')+p('If a weapon never appears, inspect enabled content before spending more rerolls. Installed content and enabled content are separate checks.')),
('beta','Check optional participation',p('Steam Library → Brotato → Properties → Betas shows participation. The 6 November announcement separates balancing from the default branch. It says this balance beta retains progression when changes move to main, and asks players to deactivate and unsubscribe from Workshop mods. '+link(NEWS,'Beta instructions'))+p('That progression statement applies to this announced beta. Keep your own backup before an experimental setup.')),
('balance','Check the current default-branch rules',p('The 12 November Balancing Patch releases the tested changes for Steam players. Gain one ban token every four waves through wave 20. Mutation effects reach 70% strength at 40 Evolution and full strength at 100. Mechanization loses extra piercing and bounces. The announcement also rebalances Jungle waves and fixes co-op shop navigation. '+link(BALANCE,'Official release notes'))+p('Weapon rebalancing entered the optional 1.2.0.4 beta on 17 November. Keep its values separate from this default-branch release and record your active Item Sets.')),
('hotfix','Match hotfix 1.2.0.3 to the symptom',p('The 13 November hotfix removes Boomerang from Caveman’s starting weapons. Snowball gains Elemental Damage from purchased or crate items, while Tumor mutations stop granting extra Elemental Damage. Weapons can now target and hit the Brachiosaurus foot, and the wave-end foot crash receives a fix for death and victory. A gamepad shop-selection issue and moving Ammosaurus attacks are also fixed. '+link(HOTFIX,'Official 1.2.0.3 notes'))),
('beta4','Use 1.2.0.4 values only on the optional beta',p('The 17 November announcement opens a new Steam beta. Opt in through Library → Brotato → Properties → Betas → beta participation → beta. Deactivate and unsubscribe from all Workshop mods first: the developer warns that outdated mods can cause crashes and corrupted saves. This announcement does not release 1.2.0.4 to the default branch or establish console or mobile availability. '+link(BETA4,'Official open-beta notes'))+table(['Weapon','1.2.0.4 beta change','What to check'],[['Carbon Bow','Damage 10 / 12 / 15 / 18; scaling 0.7 / 0.85 / 1.0 / 1.1. Added as an Engineer and Well Rounded starter.','Cursed versions now boost elemental burning and mine damage too.'],['Boomerang','Base damage doubles at every tier; Speed scaling 75 / 100 / 125 / 150%.','Added as a Wildling starter; this does not restore the Caveman starter removed in 1.2.0.3.'],['Tranq Rifle','Tier I removed; base damage and Ranged Damage scaling double on remaining tiers.','No longer a starting weapon.'],['Molotov','Fire puddle size doubles; burning damage matches Torch on every tier, duration matches from tier II.','Piercing leaves a puddle on every enemy passed through.'],['Sticky Grenade','Fuse 0.75 → 0.4 seconds; tier IV damage 28 → 31.','Piercing sticks a grenade on each enemy passed through and keeps flying.'],['Flail','Damage 13 / 18 / 24 / 32; +3 Knockback; taller attack area.','Guaranteed-critical tip area grows by 20%.']])+p('Caveman can stop the next wave’s fog thickening by burning a weapon. Mecha Parts drops rise from 1.5% to 2.5% per mecha enemy killed; Chimera Cells changes to 15% mutation chance per copy with a four-copy limit. The beta also fixes duplicated Jungle elites, Brachiosaurus foot timing and multiple feet, and caps its summons. It nerfs the health of Parasaurolophus, Alamosaurus and Pachycephalosaurus, lets Mosquitor fly over holes like other flying units, and changes early-wave enemy counts and health. The notes do not provide exact replacement enemy HP values.')+p('For shop problems, banning a locked item now releases its lock. An exhausted item pool relaxes tags, then item limits, then tier before offering banned items as a last resort. Missing challenge rewards, including characters, are re-granted on load and through “Verify challenge unlocks”. If a character is missing, record the branch before using that beta-specific remedy.')),
('report','Report a useful discrepancy',p('Include exact version, branch, map, difficulty, active sets and mods. A tooltip screenshot helps establish which rule you actually have. Use '+link('https://steamcommunity.com/app/1942280/discussions/1/','the developer-linked bug forum')+' for reproducible issues.'))]),
('mods','Brotato Mods After 1.2 — Compatibility Checklist','Check Workshop mods against Brotato 1.2, distinguish beta instructions and reproduce crashes before installing old multiplayer loaders.', 'Reproduce crashes without mods after updating to 1.2. The developer warns that outdated mods can conflict. The optional 1.2.0.4 beta repeats the instruction to deactivate and unsubscribe from all Workshop mods before playing.', 'item-set',[
('baseline','Establish the clean baseline','<ol><li>Record version, branch and subscriptions.</li><li>Back up your save before changing an experimental setup.</li><li>Deactivate mods and restart.</li><li>Repeat the failing action with the same character and Item Sets.</li><li>Check current patch notes if it still fails.</li></ol>'+p(link(NEWS,'Developer launch and beta warnings')+' support this first diagnostic step. A continuing unmodded crash needs its own reproduction report.')),
('return','Restore a compatible setup',p('Check each author’s supported version, dependencies and recent comments. Restore one compatible mod or required dependency group, restart and repeat the failing action before adding another. Workshop popularity does not establish compatibility.')+p('The 12 November balance changes are released on the Steam default branch. Record your installed version and patch date when comparing a mod author’s supported builds. For the optional 1.2.0.4 beta announced on 17 November, deactivate and unsubscribe from all Workshop mods; the developer warns that outdated mods may cause crashes and corrupted saves. Back up the save before switching, then follow '+link(BETA4,'the official beta instructions')+'. If a required mod supports only the default branch, use that supported environment.')),
('coop','Check whether a multiplayer mod is needed',p('Steam lists local co-op and Remote Play Together. Older loader tutorials may predate those features. For a normal run with friends, use the <a href="/brotato/co-op/">supported co-op setup</a> first. Identify the extra feature you need before choosing a mod.')),
('report','When the clean game still crashes',p('Compare the exact action against the November 3 Survivor co-op crate fix and hotfix 1.2.0.3, which fixes a wave-end crash while the Brachiosaurus foot is active on death or victory. The November 12 patch also adjusts modding internals for robustness, but each mod still needs its own compatibility check. A matching note is a reason to update and retry. Report version, steps and crash details if it persists. We have not validated individual packages or a universal crash fix.'))]),
('vs-vampire-survivors','Brotato vs Vampire Survivors — Choose Your Run Style','Compare Brotato and Vampire Survivors by shopping rhythm, build choices and playing with friends. Find the setup guide for your group.', 'Choose Brotato for repeated short combat waves with shop decisions between them. Choose Vampire Survivors for an extended stage run shaped by level-up choices and evolution recipes. Check the exact multiplayer mode separately.', 'base',[
('rhythm','Choose the rhythm of your decisions',table(['Preference','Starting fit','Why'],[['Frequent stops to plan purchases','Brotato','Buying, locking and rerolling sit between combat waves.'],['Continuous stage progression','Vampire Survivors','Level-up choices and evolution conditions shape the run.'],['Weapon copies and character restrictions','Brotato','The loadout develops through a character-specific shop plan.'],['Evolution combinations','Vampire Survivors','A recipe and its conditions provide a distinct progression task.']])+p('This is an editorial fit comparison based on the '+link(BASE,'Brotato description')+' and '+link('https://store.steampowered.com/app/1794680/Vampire_Survivors/','Vampire Survivors description')+'. It is not a performance benchmark.')),
('friends','Plan the group setup',p('Brotato’s Steam features include local co-op and Remote Play Together. Remote Play streams a host session. Vampire Survivors has its own mode and platform requirements. Enter your actual devices into the choice process using the <a href="/vampire-survivors/co-op/">Vampire Survivors co-op guide</a> and <a href="/brotato/co-op/">Brotato setup guide</a>.')),
('dlc','Understand the base loop first',p('If you are new to both games, learn the base loop before selecting expansion content. Brotato’s Item Sets let owners disable content to reproduce a simpler run. Primal Dread adds another decision layer through Evolution and changes enemy hazards.')),
('choose','Pick the first session',p('Choose Brotato for frequent pauses to compare purchases. Choose Vampire Survivors for planning progression through a stage. If group play decides the purchase, agree on screens, host and platforms first. Check current prices for your store and region.'))])]
